 const beam=matGlow(scene,'#72bedb',.25).clone('soft overhead shafts');beam.alpha=.035;beam.disableLighting=true;beam.backFaceCulling=false;beam.disableDepthWrite=true;for(const a of[0,Math.PI/2,Math.PI,Math.PI*1.5]){const m=BABYLON.MeshBuilder.CreateCylinder('cool light shaft',{diameterTop:.8,diameterBottom:7,height:20,tessellation:16},scene);m.position.set(64+Math.cos(a)*10,12,64+Math.sin(a)*10);m.material=beam;m.isPickable=false;world.props.push(m);}
 // Store collision boxes before render batching discards the individual meshes.
