 // Batch stationary masonry by material to keep the detailed vault inexpensive.
 const batches=new Map();for(const m of world.props)if(m.material!==beam){if(!batches.has(m.material))batches.set(m.material,[]);batches.get(m.material).push(m);}for(const[material,meshes]of batches){if(meshes.length<2)continue;const merged=BABYLON.Mesh.MergeMeshes(meshes,true,true,undefined,false,false);merged.name='Crucible architecture · '+material.name;merged.material=material;merged.receiveShadows=true;world.chunks.push(merged);}world.props=world.props.filter(m=>!m.isDisposed());
